@Component("taxWithholding-handler")
@ProcessingGroup("taxWithholding-processing-group")
public class TaxWithholdingEventHandler {
	
	// core constructor
	TaxWithholdingEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateTaxWithholdingEvent
     */
    @EventHandler
    public void handle( CreateTaxWithholdingEvent event) {
        entityManager.persist(new TaxWithholding(event.getTaxWithholdingId(), event.getTaxId(), event.getAllowances(), event.getAdditionalAmount(), event.getEmployee(), event.getFilingStatus()));
    }

    /*
     * @param	event UpdateTaxWithholdingEvent
     */
    @EventHandler
    public TaxWithholding handle( UpdateTaxWithholdingEvent event) {
    	entityManager.merge(new TaxWithholding(event.getTaxWithholdingId(), event.getTaxId(), event.getAllowances(), event.getAdditionalAmount(), event.getEmployee(), event.getFilingStatus()));
    }
    
    /*
     * @param	event DeleteTaxWithholdingEvent
     */
    @EventHandler
    public void on( DeleteTaxWithholdingEvent event) {
    	TaxWithholding entity = new TaxWithholding();
   
    	// ------------------------------------------
    	// apply the TaxWithholdingId
    	// ------------------------------------------
    	entity.setTaxWithholdingId( event.getTaxWithholdingId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final TaxWithholdingRepository taxWithholdingEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(TaxWithholdingEventHandler.class.getName());

}
